def calculate_a(N):
    # Initialize memoization dictionary
    memo = {}

    def a(n):
        if n in memo:
            return memo[n]
        if n == 1:
            return 0

        k = n // 2

        if n % 2 == 0:
            # n = 2k (Even)
            # a_n = 2 * a_k + k
            result = 2 * a(k) + k
        else:
            # n = 2k + 1 (Odd)
            # a_n = a_k + a_{k+1} + k
            result = a(k) + a(k + 1) + k

        memo[n] = result
        return result

    return a(N)

# We need to calculate a_2025
N_target = 2025
result = calculate_a(N_target)
print(result)
